let LANG='pt';try{LANG=localStorage.getItem('md-lang')||'pt';}catch(e){}
const L10N_ORIG=new WeakMap(),L10N_ATTR=['placeholder','title','aria-label','label'];let l10nBusy=false;
function tEN(t){if(!t)return t;for(const [a,b] of I18N_EN)if(t.includes(a))t=t.split(a).join(b);return t;}
const l10n=t=>LANG==='pt'?t:tEN(t);
function l10nNode(n){
  if(n.nodeType===3){if(n.parentElement&&n.parentElement.closest('script,style,textarea'))return;
    let o=L10N_ORIG.get(n);if(o==null||(n.nodeValue!==tEN(o)&&n.nodeValue!==o))o=n.nodeValue;L10N_ORIG.set(n,o);const v=l10n(o);if(n.nodeValue!==v)n.nodeValue=v;return;}
  if(n.nodeType!==1||n.matches('script,style'))return;
  let m=L10N_ORIG.get(n);if(!m){m={};L10N_ORIG.set(n,m);}
  for(const a of L10N_ATTR){const cur=n.getAttribute(a);if(cur==null)continue;if(m[a]==null||(cur!==tEN(m[a])&&cur!==m[a]))m[a]=cur;const v=l10n(m[a]);if(cur!==v)n.setAttribute(a,v);}
  for(const c of n.childNodes)l10nNode(c);
}
function l10nAll(){l10nBusy=true;l10nNode(document.body);document.title='Marshall Simulator';l10nBusy=false;}
new MutationObserver(ms=>{if(l10nBusy||LANG==='pt')return;l10nBusy=true;
  for(const m of ms){if(m.type==='childList')m.addedNodes.forEach(l10nNode);else l10nNode(m.target);}l10nBusy=false;})
  .observe(document.body,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:L10N_ATTR});
function setLang(l){LANG=l;try{localStorage.setItem('md-lang',l);}catch(e){}document.documentElement.lang=l==='en'?'en':'pt-BR';
  document.querySelectorAll('.lang .btn').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.lang===l)));l10nAll();}
document.querySelectorAll('.lang .btn').forEach(b=>b.addEventListener('click',()=>setLang(b.dataset.lang)));
setLang(LANG);

