const FINES={L:[0.79,0.99,2.38,3.58,82.61],G:[0.78,1.42,1.46,4.01,81.88]}; // % massa < 2 mm de L5..L1 / G5..G1
const TYPE_RANGE=[[14,20],[10,14],[6,10],[4,6],[0.063,4]];
function wGradation(m){
  const stone=m[0],shares=m.slice(1,6),filler=m[6];
  const sieves=[20,16,14,12.5,10,8,6.3,4,2.8,2,1,0.5,0.25,0.125,0.063];
  const parts=[];
  shares.forEach((sh,k)=>{if(!sh)return;const pf=FINES[stone][k]/100,[lo,hi]=TYPE_RANGE[k];
    parts.push({m:sh*pf,a:0.063,b:2});parts.push({m:sh*(1-pf),a:Math.max(lo,2),b:hi});});
  const below=(p,s)=>Math.min(1,Math.max(0,(Math.log(s)-Math.log(p.a))/(Math.log(p.b)-Math.log(p.a))));
  let pass=sieves.map(s=>filler+parts.reduce((t,p)=>t+p.m*below(p,s),0));
  const tot=filler+shares.reduce((a,b)=>a+b,0);pass=pass.map(v=>Math.round(v/tot*1000)/10);
  let first=pass.findIndex(v=>v<100);first=Math.max(0,first-1);
  return {sieves:sieves.slice(first),pass:pass.slice(first).map((v,i)=>i===0?100:v)};
}
const midOf=p=>p[1]!=null&&p[2]!=null?(p[1]+p[2])/2:(p[2]!=null?p[2]:p[1]);
let USERCURVES=[];
const curveById=id=>GRADLIB.find(c=>c.id===id)||USERCURVES.find(c=>c.id===id);
