const store={
  async load(){if(hasPy()){try{return JSON.parse(await window.pywebview.api.load_curves()||'[]');}catch(e){return [];}}
    try{return JSON.parse(localStorage.getItem('md-curvas')||'[]');}catch(e){return [];}},
  async save(list){const t=JSON.stringify(list);if(hasPy()){await window.pywebview.api.save_curves(t);return 'minhas_curvas.json';}
    try{localStorage.setItem('md-curvas',t);return 'este navegador';}catch(e){return null;}}
};
