function buildCurveSelect(){
  const sel=$('f-curve'),byC={BR:'Brasil',US:'EUA',DE:'Alemanha'};
  let html='';
  if(USERCURVES.length)html+='<optgroup label="Minhas curvas">'+USERCURVES.map(c=>`<option value="lib:${c.id}">${c.des.replace(/</g,'&lt;')}</option>`).join('')+'</optgroup>';
  for(const pais of ['BR','US','DE']){const cs=GRADLIB.filter(c=>c.pais===pais);if(!cs.length)continue;
    html+=`<optgroup label="Faixas · ${byC[pais]} (meio da faixa)">`+cs.map(c=>`<option value="lib:${c.id}">${curveLabel(c)}</option>`).join('')+'</optgroup>';}
  html+='<optgroup label="Misturas de Wan et al. (Tabela 1)">'+WMIX.map((m,i)=>`<option value="w:${i}">Mistura ${i+1} (${m[0]==='L'?'calcário':'granito'}, AVC ${fmt(m[8],1)}%)</option>`).join('')+'</optgroup>';
  sel.innerHTML=html;sel.value=preset;
}
buildCurveSelect();
$('f-curve').addEventListener('change',()=>{const v=$('f-curve').value;v.startsWith('w:')?loadW(+v.slice(2)):loadCurve(v.slice(4));});
function parseCurveText(txt){
  const pts=[];
  for(let line of txt.split(/\r?\n/)){line=line.trim();if(!line)continue;
    let cols=/[;\t]/.test(line)?line.split(/[;\t]+/):(/\d\.\d/.test(line)&&line.includes(','))?line.split(','):line.split(/\s+/);
    cols=cols.map(c=>parseNum(c.trim())).filter(v=>!isNaN(v));
    if(cols.length===2)pts.push([cols[0],cols[1],cols[1]]);else if(cols.length>=3)pts.push([cols[0],Math.min(cols[1],cols[2]),Math.max(cols[1],cols[2])]);}
  pts.sort((x,y)=>y[0]-x[0]);
  if(pts.length<3)return {err:'Informe pelo menos 3 peneiras.'};
  if(pts.some(p=>p[0]<=0||p[1]<0||p[2]>100))return {err:'As peneiras devem ser > 0 mm e a % passante entre 0 e 100.'};
  for(let i=1;i<pts.length;i++)if(midOf(pts[i])>midOf(pts[i-1])+1e-9)return {err:`A % passante cresce na peneira de ${fmt(pts[i][0],3)} mm.`};
  if(!pts.some(p=>p[0]>2))return {err:'Inclua peneiras acima de 2 mm.'};
  if(midOf(pts[0])<100)pts.unshift([+(pts[0][0]*1.5).toFixed(1),100,100]);
  return {pts};
}
function openCurveBox(fromTable){
  $('nc-box').hidden=false;$('nc-err').textContent='';
  $('nc-where').textContent=hasPy()?'A curva fica salva no arquivo minhas_curvas.json do Marshall Simulator.':'A curva fica salva neste navegador.';
  if(fromTable){$('nc-nome').value=$('f-nome').value+' (minha)';$('nc-txt').value=rows.map(r=>`${r.s}; ${r.p}`).join('\n');}
  else{$('nc-nome').value='';$('nc-txt').value='';}
  $('nc-nome').focus();
}
$('b-newcurve').addEventListener('click',()=>openCurveBox(false));
$('b-savecurve').addEventListener('click',()=>openCurveBox(true));
$('nc-cancel').addEventListener('click',()=>{$('nc-box').hidden=true;});
$('nc-file').addEventListener('change',e=>{const f=e.target.files[0];if(!f)return;const rd=new FileReader();
  rd.onload=()=>{$('nc-txt').value=rd.result;if(!$('nc-nome').value)$('nc-nome').value=f.name.replace(/\.[^.]+$/,'');};rd.readAsText(f);e.target.value='';});
$('nc-ok').addEventListener('click',async()=>{
  const nome=$('nc-nome').value.trim();if(!nome){$('nc-err').textContent='Dê um nome à curva.';return;}
  const r=parseCurveText($('nc-txt').value);if(r.err){$('nc-err').textContent=r.err;return;}
  const hasBand=r.pts.some(p=>p[2]-p[1]>1e-9),gi=r.pts.findIndex(p=>midOf(p)<90);
  const c={id:'user:'+Date.now().toString(36),pais:'USR',norma:'Minha curva',des:nome,fam:hasBand?'Faixa do usuário':'Curva do usuário',ed:new Date().toLocaleDateString('pt-BR'),
    nmas:gi>0?r.pts[gi-1][0]:r.pts[0][0],dmax:r.pts[0][0],pts:r.pts.map(p=>[p[0],p[1],p[2],'U']),ctl:false,user:true,band:hasBand};
  USERCURVES.push(c);const where=await store.save(USERCURVES);
  preset='lib:'+c.id;buildCurveSelect();loadCurve(c.id);$('nc-box').hidden=true;
  $('n-curve').textContent+=where?` · salva em ${where}`:' · não foi possível salvar (armazenamento bloqueado)';
});
$('b-delcurve').addEventListener('click',async()=>{
  const b=$('b-delcurve');
  if(b.dataset.armed!=='1'){b.dataset.armed='1';b.textContent='Confirmar exclusão';setTimeout(()=>{b.dataset.armed='';b.textContent='Excluir esta curva';},4000);return;}
  b.dataset.armed='';b.textContent='Excluir esta curva';
  USERCURVES=USERCURVES.filter(c=>'lib:'+c.id!==preset);await store.save(USERCURVES);
  preset='lib:'+DEFAULT_CURVE;buildCurveSelect();loadCurve(DEFAULT_CURVE);
});
async function reloadUserCurves(){USERCURVES=await store.load();buildCurveSelect();}
reloadUserCurves();window.addEventListener('pywebviewready',reloadUserCurves);
