function readForm(){
  const errs={},cfg={};
  cfg.nome=$('f-nome').value.trim()||'Mistura';
  const g=rows.map(r=>({s:parseNum(r.s),p:parseNum(r.p)}));
  let ge='';
  if(g.some(r=>!isFinite(r.s)||!isFinite(r.p)||r.s<=0||r.p<0||r.p>100))ge='Preencha todas as peneiras (mm > 0) e % passante entre 0 e 100.';
  else{g.sort((a,b)=>b.s-a.s);
    for(let i=1;i<g.length;i++)if(g[i].p>g[i-1].p+1e-9){ge=`A % passante não pode crescer com peneiras menores (${fmt(g[i].s,3)} mm).`;break;}
    if(!ge&&Math.abs(g[0].p-100)>1e-6)ge='A peneira de maior abertura deve ter 100% passante.';
    if(!ge&&!g.some(r=>r.s>2))ge='Inclua peneiras acima de 2 mm.';}
  if(ge)errs.grad=ge;cfg.grad=g;
  cfg.pb=parseNum($('f-pb').value);if(!(cfg.pb>=2&&cfg.pb<=10))errs.pb='Use um teor de betume entre 2 e 10%.';
  cfg.avc=parseNum($('f-avc').value);if(!(cfg.avc>=0.5&&cfg.avc<=30))errs.avc='Use vazios entre 0,5 e 30%.';
  cfg.ra=parseNum($('f-ra').value);if(!(cfg.ra>=1.5&&cfg.ra<=4))errs.ra='Use uma densidade entre 1,5 e 4,0.';
  cfg.rb=parseNum($('f-rb').value);if(!(cfg.rb>=0.9&&cfg.rb<=1.2))errs.rb='Use uma densidade entre 0,9 e 1,2.';
  cfg.seed=Math.round(parseNum($('f-seed').value))||2024;
  cfg.lib=$('f-lib').value;cfg.size=$('f-size').value;
  cfg.bub={mode:$('f-bub').value,B:parseNum($('f-bB').value),BScmm:parseNum($('f-bSc').value),BSh:parseNum($('f-bSh').value)};
  if(cfg.bub.mode==='manual'&&!(cfg.bub.B>=0&&cfg.bub.B<=100&&cfg.bub.BScmm>0&&cfg.bub.BSh>0))errs.grad=(errs.grad?errs.grad+' ':'')+'Revise os valores manuais das bolhas.';
  cfg.seg={on:$('f-seg').checked,k:+$('f-segk').value};
  cfg.preset=preset;
  // compactação: protocolo, modo de AVC, golpes/giros, betume e temperatura, calibração do mastique
  cfg.proto=$('f-proto').value;cfg.avcMode=cfg.proto==='w'?'travado':$('f-avcmode').value;
  cfg.golpes=+$('f-golpes').value;cfg.gsim=+$('f-gsim').value;
  cfg.ngir=Math.round(parseNum($('f-ngir').value));cfg.gsimg=+$('f-gsimg').value;
  cfg.press=parseNum($('f-press').value);cfg.ang=parseNum($('f-ang').value);
  cfg.grade=$('f-grade').value;cfg.temp=parseNum($('f-temp').value);
  cfg.lam=parseNum($('f-lam').value);cfg.etaK=parseNum($('f-etak').value);cfg.escE=parseNum($('f-escE').value);cfg.escP=parseNum($('f-escP').value);cfg.faceW=parseNum($('f-facew').value);
  if(cfg.proto!=='w'){
    if(!(cfg.temp>=90&&cfg.temp<=200))errs.temp='Use uma temperatura entre 90 e 200 °C.';
    const bad=[];
    if(!(cfg.lam>=0.05&&cfg.lam<=2))bad.push('λ entre 0,05 e 2');
    if(!(cfg.etaK>=0.01&&cfg.etaK<=100))bad.push('fator de viscosidade entre 0,01 e 100');
    if(cfg.proto==='marshall'&&!(cfg.escE>0&&cfg.escE<=1))bad.push('escala de energia entre 0 e 1');
    if(cfg.proto==='giratorio'){
      if(!(cfg.ngir>=5&&cfg.ngir<=300))bad.push('giros entre 5 e 300');
      if(!(cfg.press>=100&&cfg.press<=1000))bad.push('pressão entre 100 e 1000 kPa');
      if(!(cfg.ang>=0.5&&cfg.ang<=3))bad.push('ângulo entre 0,5 e 3°');
      if(!(cfg.escP>0&&cfg.escP<=1))bad.push('escala de pressão entre 0 e 1');}
    if(bad.length)errs.temp=(errs.temp?errs.temp+' ':'')+'Revise: '+bad.join('; ')+'.';
  }
  if(!(cfg.faceW>=0.5&&cfg.faceW<=10))errs.grad=(errs.grad?errs.grad+' ':'')+'Use um peso das faces entre 0,5 e 10.';
  return {cfg,errs};
}
function showErrs(errs){
  [['grad','e-grad'],['pb','e-pb'],['avc','e-avc'],['ra','e-ra'],['rb','e-rb'],['temp','e-temp']].forEach(([k,id])=>{$(id).textContent=errs[k]||'';});
  [['pb','f-pb'],['avc','f-avc'],['ra','f-ra'],['rb','f-rb'],['temp','f-temp']].forEach(([k,id])=>$(id).classList.toggle('bad',!!errs[k]));
}

